/**
 * TypeScript port of the backend claim verifier (matchdesk.domain.verification) and its
 * registered metrics (matchdesk.domain.metrics).
 *
 * It mirrors verify_claim branch for branch: evidence binding, claim kinds, the metric
 * registry, unit checks, recomputation and the comparator, including precision-aware
 * equality. apps/web/tests/verifier.parity.test.mjs runs it on every case in
 * verifier-parity.json, generated by the real Python verifier, and requires identical
 * status, query, reason, expected and observed values. It has no imports, so Node can load
 * it directly. It does not hash evidence records; the server's evidence digest stays
 * authoritative.
 */

export type Status = "verified" | "supported_inference" | "needs_revision" | "blocked";

export type Window = { period?: 1 | 2 | null; from_ms: number; to_ms: number };
export type Subject = { team_id?: string | null; player_id?: string | null };
export type Assertion = {
  metric: string;
  subject: Subject;
  window: Window;
  comparator?: "eq" | "gte" | "lte";
  value: number;
  unit: string;
  decimals?: number | null;
};
export type EventFact = {
  query: "goal_scorer.v1" | "sequence_gap.v1";
  event_id: string;
  player_id?: string | null;
  from_event_id?: string | null;
  from_tag?: string | null;
  gap_seconds?: number | null;
};
export type Claim = {
  claim_id: string;
  text: string;
  kind: "measured_stat" | "event_fact" | "tactical_inference";
  assertion?: Assertion | null;
  fact?: EventFact | null;
  evidence_event_ids: readonly string[];
};
/** Display names the prose uses, by player or team identity. */
export type Names = Readonly<Record<string, string>>;
export type Evidence = { match_id: string; event_ids: readonly string[]; window?: Window };
export type Result = {
  claim_id: string;
  status: Status;
  query_id: string;
  reason: string;
  expected: number | null;
  observed: number | null;
};

/** The fields of a match event that the registered metrics and evidence binding read. */
export type VEvent = {
  event_id: string;
  match_id: string;
  sequence: number;
  period: 1 | 2;
  match_clock_ms: number;
  type: string;
  team_id: string | null;
  player_id: string | null;
  outcome: string | null;
  xg: number | null;
  x: number | null;
  end_x: number | null;
  tags: readonly string[];
};

/** Column-oriented log, as written by matchdesk.domain.verifier_parity.compact_events. */
export type CompactLog = {
  match_ids: readonly string[];
  id: readonly string[];
  seq: readonly number[];
  period: readonly (1 | 2)[];
  ms: readonly number[];
  type: readonly string[];
  team: readonly (string | null)[];
  player: readonly (string | null)[];
  outcome: readonly (string | null)[];
  xg: readonly (number | null)[];
  x: readonly (number | null)[];
  end_x: readonly (number | null)[];
  tags?: readonly (readonly string[])[];
};

export function expandLog(log: CompactLog): VEvent[] {
  return log.id.map((event_id, i) => ({
    event_id,
    match_id: log.match_ids[i],
    sequence: log.seq[i],
    period: log.period[i],
    match_clock_ms: log.ms[i],
    type: log.type[i],
    team_id: log.team[i],
    player_id: log.player[i],
    outcome: log.outcome[i],
    xg: log.xg[i],
    x: log.x[i],
    end_x: log.end_x[i],
    tags: log.tags ? log.tags[i] : [],
  }));
}

/* ---------- Metrics (matchdesk.domain.metrics) ---------- */

class MetricError extends Error {}

const FINAL_THIRD_X = 200.0 / 3.0;

export const METRIC_UNITS: Readonly<Record<string, string>> = {
  "shots.v1": "count",
  "goals.v1": "count",
  "pass_accuracy.v1": "ratio",
  "synthetic_xg.v1": "synthetic_xg",
  "final_third_entries.v1": "count",
  "possession_time.v1": "ratio",
};

function eventsInWindow(events: readonly VEvent[], window: Window): VEvent[] {
  if (!events.length) return [];
  const matchId = events[0].match_id;
  let previous: number | null = null;
  for (const event of events) {
    if (event.match_id !== matchId) throw new MetricError("metric input cannot mix match identities");
    if (previous !== null && event.sequence <= previous) throw new MetricError("metric input must be in strictly increasing sequence order");
    previous = event.sequence;
  }
  return events.filter((e) => (window.period == null || e.period === window.period) && window.from_ms <= e.match_clock_ms && e.match_clock_ms < window.to_ms);
}

function matchesSubject(event: VEvent, subject: Subject): boolean {
  if (subject.team_id != null && event.team_id !== subject.team_id) return false;
  if (subject.player_id != null && event.player_id !== subject.player_id) return false;
  return true;
}

function countOf(type: string) {
  return (events: readonly VEvent[], subject: Subject, window: Window) =>
    eventsInWindow(events, window).filter((e) => e.type === type && matchesSubject(e, subject)).length;
}

function passAccuracy(events: readonly VEvent[], subject: Subject, window: Window): number {
  const passes = eventsInWindow(events, window).filter((e) => e.type === "pass" && matchesSubject(e, subject));
  if (!passes.length) return 0;
  return passes.filter((e) => e.outcome === "complete").length / passes.length;
}

function syntheticXg(events: readonly VEvent[], subject: Subject, window: Window): number {
  let total = 0;
  for (const e of eventsInWindow(events, window)) if (e.type === "shot" && matchesSubject(e, subject)) total += e.xg || 0;
  return total;
}

function finalThirdEntries(events: readonly VEvent[], subject: Subject, window: Window): number {
  let count = 0;
  for (const e of eventsInWindow(events, window)) {
    if (!(e.type === "pass" || e.type === "carry" || e.type === "dribble") || e.outcome !== "complete") continue;
    if (!matchesSubject(e, subject)) continue;
    if ((e.x as number) < FINAL_THIRD_X && FINAL_THIRD_X <= (e.end_x as number)) count += 1;
  }
  return count;
}

function possessionTime(events: readonly VEvent[], subject: Subject, window: Window): number {
  if (subject.team_id == null || subject.player_id != null) throw new MetricError("possession_time.v1 requires a team-only subject");
  if (!events.length) return 0;
  eventsInWindow(events, window);
  const owned = new Map<string, number>();
  for (const period of window.period == null ? [1, 2] : [window.period]) {
    const inPeriod = events.filter((e) => e.period === period);
    for (let i = 0; i + 1 < inPeriod.length; i += 1) {
      const current = inPeriod[i];
      if (current.team_id == null) continue;
      const start = Math.max(current.match_clock_ms, window.from_ms);
      const end = Math.min(inPeriod[i + 1].match_clock_ms, window.to_ms);
      if (end <= start) continue;
      owned.set(current.team_id, (owned.get(current.team_id) ?? 0) + (end - start));
    }
  }
  let total = 0;
  for (const ms of owned.values()) total += ms;
  if (total === 0) return 0;
  return (owned.get(subject.team_id) ?? 0) / total;
}

const FORMULAS: Readonly<Record<string, (events: readonly VEvent[], subject: Subject, window: Window) => number>> = {
  "shots.v1": countOf("shot"),
  "goals.v1": countOf("goal"),
  "pass_accuracy.v1": passAccuracy,
  "synthetic_xg.v1": syntheticXg,
  "final_third_entries.v1": finalThirdEntries,
  "possession_time.v1": possessionTime,
};

export function computeMetric(metric: string, events: readonly VEvent[], subject: Subject, window: Window): number {
  const formula = FORMULAS[metric];
  if (!formula) throw new MetricError(`unregistered metric: ${metric}`);
  return formula(events, subject, window);
}

/* ---------- Precision (matchdesk.domain.models.round_half_up) ---------- */

/** Plain decimal digits of a number's shortest round-trip form (JS and Python agree on it). */
function plainDecimal(value: number): { negative: boolean; int: string; frac: string } {
  const text = String(Math.abs(value));
  const [mantissa, exp = "0"] = text.split(/e/i);
  const [whole, fraction = ""] = mantissa.split(".");
  let digits = whole + fraction;
  let point = whole.length + Number(exp);
  if (point <= 0) { digits = "0".repeat(1 - point) + digits; point = 1; }
  if (point > digits.length) digits += "0".repeat(point - digits.length);
  return { negative: value < 0, int: digits.slice(0, point).replace(/^0+(?=\d)/, ""), frac: digits.slice(point) };
}

/** Round half up (away from zero on ties) at `decimals` places; returns a canonical string. */
export function roundHalfUp(value: number, decimals: number): string {
  const { negative, int, frac } = plainDecimal(value);
  const padded = (frac + "0".repeat(decimals + 1)).slice(0, decimals + 1);
  let kept = (int + padded.slice(0, decimals)).split("").map(Number);
  if (padded[decimals] >= "5") {
    let i = kept.length - 1;
    while (i >= 0 && kept[i] === 9) { kept[i] = 0; i -= 1; }
    if (i < 0) kept = [1, ...kept]; else kept[i] += 1;
  }
  const digits = kept.join("");
  const whole = digits.slice(0, digits.length - decimals).replace(/^0+(?=\d)/, "") || "0";
  const rounded = decimals ? `${whole}.${digits.slice(digits.length - decimals)}` : whole;
  return negative && /[1-9]/.test(rounded) ? `-${rounded}` : rounded;
}

function comparisonPasses(comparator: string, expected: number, observed: number, decimals: number | null | undefined): boolean {
  if (comparator === "eq" && decimals != null) return roundHalfUp(observed, decimals) === roundHalfUp(expected, decimals);
  if (comparator === "eq") return Math.abs(observed - expected) <= Math.max(1e-9 * Math.max(Math.abs(observed), Math.abs(expected)), 1e-9);
  if (comparator === "gte") return observed >= expected;
  if (comparator === "lte") return observed <= expected;
  throw new Error(`unsupported comparator: ${comparator}`);
}

/* ---------- Claim text (matchdesk.domain.claim_text) ---------- */

const NUMBER_WORDS: Readonly<Record<string, number>> = {
  zero: 0, one: 1, once: 1, two: 2, twice: 2, both: 2, brace: 2, double: 2, three: 3, thrice: 3,
  "hat-trick": 3, "hat trick": 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10,
  eleven: 11, twelve: 12,
};
const escapeRegExp = (text: string) => text.replace(/[.*+?^${}()|[\]\\\-]/g, "\\$&");
const B = "(?<![A-Za-z0-9_])";
const E = "(?![A-Za-z0-9_])";
const WORDS = new RegExp(`${B}(${Object.keys(NUMBER_WORDS).sort((a, b) => b.length - a.length).map(escapeRegExp).join("|")})${E}`, "g");
const CLOCK = /[0-9]{1,3}:[0-9]{2}/g;
const SCORELINE = new RegExp(`${B}[0-9]+\\s*[-–—]\\s*[0-9]+${E}`, "g");
const MINUTE = new RegExp(`${B}[0-9]+\\s*(?:'|′|’|(?:st|nd|rd|th|mins?|minutes?)${E})`, "g");
const PERCENT = new RegExp(`${B}([0-9]+(?:\\.[0-9]+)?)\\s*(?:%|per\\s?cent${E})`, "g");
const DIGITS = new RegExp(`${B}[0-9]+(?:\\.[0-9]+)?${E}`, "g");
export const TEXT_QUERY_ID = "claim-text-binding-v1";

/** The counts and percentages a sentence states, ignoring clocks, scorelines and minutes. */
export function statedQuantities(text: string): { counts: number[]; percents: number[] } {
  let lowered = text.toLowerCase().replace(/’/g, "'");
  lowered = lowered.replace(CLOCK, " ").replace(SCORELINE, " ");
  const percents = [...lowered.matchAll(PERCENT)].map((m) => Number(m[1]));
  lowered = lowered.replace(PERCENT, " ").replace(MINUTE, " ");
  const counts = [...lowered.matchAll(DIGITS)].map((m) => Number(m[0]));
  for (const m of lowered.matchAll(WORDS)) counts.push(NUMBER_WORDS[m[1]]);
  return { counts, percents };
}

function expectedQuantity(claim: Claim): ["count" | "percent", number] | null {
  const assertion = claim.assertion;
  if (assertion) {
    if (assertion.unit === "count") return ["count", assertion.value];
    if (assertion.unit === "ratio") {
      const places = assertion.decimals == null ? 6 : Math.max(assertion.decimals - 2, 0);
      return ["percent", Number(roundHalfUp(assertion.value * 100, places))];
    }
    return null;
  }
  if (claim.fact && claim.fact.gap_seconds != null) return ["count", claim.fact.gap_seconds];
  return null;
}

function subjectId(claim: Claim): string | null {
  if (claim.assertion) return claim.assertion.subject.player_id || claim.assertion.subject.team_id || null;
  if (claim.fact) return claim.fact.player_id ?? null;
  return null;
}

/** Why the sentence does not match its structured claim, or null if it does. */
export function textBindingProblem(claim: Claim, names?: Names | null): string | null {
  const expected = expectedQuantity(claim);
  if (expected) {
    const [kind, value] = expected;
    const stated = statedQuantities(claim.text);
    const found = kind === "count" ? stated.counts : stated.percents;
    if (found.some((q) => q !== value)) return "Claim text states a quantity that differs from its assertion";
    if (names && !found.includes(value)) return "Claim text does not state the asserted value";
  }
  if (names) {
    const subject = subjectId(claim);
    if (subject != null) {
      const name = names[subject];
      if (name === undefined) return "Claim subject has no registered display name";
      if (!new RegExp(B + escapeRegExp(name.toLowerCase()) + E).test(claim.text.toLowerCase())) return "Claim text does not name the asserted subject";
    }
  }
  return null;
}

/* ---------- Verification (matchdesk.domain.verification) ---------- */

const queryId = (metric: string) => `metric-${metric.replace(/\./g, "-")}`;
const COUNTED_TYPES: Readonly<Record<string, string>> = { "goals.v1": "goal", "shots.v1": "shot" };

function validateEvidence(claim: Claim, evidence: Evidence, events: readonly VEvent[]): string | null {
  if (!events.length) return "No accepted events are available for verification";
  if (events.some((e) => e.match_id !== evidence.match_id)) return "Verification input contains events outside the evidence match";
  const eventIds = new Set(events.map((e) => e.event_id));
  const recordIds = new Set(evidence.event_ids);
  if (claim.evidence_event_ids.some((id) => !recordIds.has(id))) return "Claim cites events that are not bound by the evidence record";
  if (claim.evidence_event_ids.some((id) => !eventIds.has(id))) return "Claim cites events that are not present in accepted event input";
  return null;
}

function factResult(claim: Claim, fact: EventFact, evidence: Evidence, events: readonly VEvent[]): [Status, string, string] {
  const query = "event-" + fact.query.replace(/\./g, "-").replace(/_/g, "-");
  const referenced = fact.from_event_id == null ? [fact.event_id] : [fact.from_event_id, fact.event_id];
  if (referenced.some((id) => !claim.evidence_event_ids.includes(id))) return ["blocked", query, "Event fact reads events the claim does not cite"];
  const byId = new Map(events.map((e) => [e.event_id, e]));
  const target = byId.get(fact.event_id) as VEvent;
  if (evidence.window && target.match_clock_ms >= evidence.window.to_ms) return ["blocked", query, "Event fact reads events after the evidence window"];
  if (fact.query === "goal_scorer.v1") {
    return target.type === "goal" && target.player_id === fact.player_id
      ? ["verified", query, "The cited goal event records the stated scorer"]
      : ["needs_revision", query, "The cited event is not a goal by the stated player"];
  }
  const earlier = byId.get(fact.from_event_id as string) as VEvent;
  if (earlier.sequence >= target.sequence) return ["needs_revision", query, "The cited events are not in the stated order"];
  if (fact.from_tag != null && !earlier.tags.includes(fact.from_tag)) return ["needs_revision", query, `The earlier event is not tagged ${fact.from_tag}`];
  const gap = Number(roundHalfUp((target.match_clock_ms - earlier.match_clock_ms) / 1000, 0));
  if (gap !== fact.gap_seconds) return ["needs_revision", query, "The recorded gap differs from the stated seconds"];
  return ["verified", query, "The recorded events and gap match the stated sequence"];
}

function citesCountedEvents(claim: Claim, assertion: Assertion, events: readonly VEvent[], type: string): boolean {
  const { window, subject } = assertion;
  const counted = new Set(events.filter((e) => e.type === type
    && (window.period == null || e.period === window.period)
    && window.from_ms <= e.match_clock_ms && e.match_clock_ms < window.to_ms
    && (subject.team_id == null || e.team_id === subject.team_id)
    && (subject.player_id == null || e.player_id === subject.player_id)).map((e) => e.event_id));
  return claim.evidence_event_ids.every((id) => counted.has(id));
}

/** Verify one claim against evidence and accepted events, exactly as the backend does. */
export function verifyClaim(claim: Claim, evidence: Evidence, events: readonly VEvent[], names?: Names | null): Result {
  const base = { claim_id: claim.claim_id, expected: null, observed: null };
  const blocking = validateEvidence(claim, evidence, events);
  if (blocking) return { ...base, status: "blocked", query_id: "evidence-binding-v1", reason: blocking };
  if (claim.assertion && evidence.window && claim.assertion.window.to_ms > evidence.window.to_ms) {
    return { ...base, status: "blocked", query_id: "evidence-window-v1", reason: "Claim window extends past the evidence window" };
  }
  if (claim.kind === "tactical_inference") {
    return { ...base, status: "supported_inference", query_id: "evidence-support-v1", reason: "All cited evidence events exist; tactical meaning remains an inference" };
  }
  if (claim.kind === "event_fact" && claim.fact) {
    let [status, query_id, reason] = factResult(claim, claim.fact, evidence, events);
    if (status === "verified") {
      const problem = textBindingProblem(claim, names);
      if (problem) [status, query_id, reason] = ["needs_revision", TEXT_QUERY_ID, problem];
    }
    return { ...base, status, query_id, reason };
  }
  if (claim.kind === "event_fact") {
    return { ...base, status: "needs_revision", query_id: "event-fact-semantic-v1", reason: "Event-fact prose has no registered semantic assertion; evidence existence alone cannot verify the text" };
  }
  const assertion = claim.assertion;
  if (!assertion) throw new Error("Measured claim is missing its required metric assertion");
  const unit = METRIC_UNITS[assertion.metric];
  if (unit === undefined) return { ...base, status: "blocked", query_id: "metric-registry-v1", reason: `Metric is not registered: ${assertion.metric}` };
  if (assertion.unit !== unit) {
    return { ...base, status: "blocked", query_id: queryId(assertion.metric), reason: `Claim unit ${assertion.unit} does not match registered metric unit ${unit}` };
  }
  let observed: number;
  try {
    observed = computeMetric(assertion.metric, events, assertion.subject, assertion.window);
  } catch (error) {
    if (!(error instanceof MetricError)) throw error;
    return { ...base, status: "blocked", query_id: queryId(assertion.metric), reason: `Metric recomputation failed: ${error.message}`, expected: assertion.value };
  }
  let passed = comparisonPasses(assertion.comparator ?? "eq", assertion.value, observed, assertion.decimals);
  let query_id = queryId(assertion.metric);
  let reason = passed ? "Registered metric recomputation satisfies the claim comparator" : "Registered metric recomputation does not satisfy the claim comparator";
  const countedType = COUNTED_TYPES[assertion.metric];
  if (passed && countedType !== undefined && !citesCountedEvents(claim, assertion, events, countedType)) {
    passed = false;
    reason = "Claim cites events the registered metric does not count";
  }
  if (passed) {
    const problem = textBindingProblem(claim, names);
    if (problem) { passed = false; query_id = TEXT_QUERY_ID; reason = problem; }
  }
  return { claim_id: claim.claim_id, status: passed ? "verified" : "needs_revision", query_id, reason, expected: assertion.value, observed };
}
